<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Database;
final class ReportService{
 public static function dashboard():array{
  $pdo=Database::connection();$q=fn(string $sql)=>(int)$pdo->query($sql)->fetchColumn();
  $stats=['products'=>$q("SELECT COUNT(*) FROM products WHERE is_active=1"),'without_price'=>$q("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND NOT EXISTS(SELECT 1 FROM product_prices x WHERE x.product_id=p.id)"),'expired'=>$q("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND EXISTS(SELECT 1 FROM product_prices x WHERE x.product_id=p.id) AND DATEDIFF(DAY,(SELECT MAX(y.price_received_at) FROM product_prices y WHERE y.product_id=p.id),SYSDATETIME())>=30"),'queue'=>$q("SELECT COUNT(*) FROM price_queue WHERE status IN('new','in_progress','needs_followup')"),'critical'=>$q("SELECT COUNT(*) FROM price_queue WHERE priority_level='critical' AND status IN('new','in_progress','needs_followup')"),'suppliers'=>$q("SELECT COUNT(*) FROM suppliers WHERE is_active=1"),'incomplete_sources'=>$q("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND (SELECT COUNT(*) FROM product_sources ps WHERE ps.product_id=p.id AND ps.expected=1 AND ps.is_active=1)<p.min_sources"),'high_spread'=>$q("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND EXISTS(SELECT 1 FROM product_prices a WHERE a.product_id=p.id) AND (SELECT AVG(x.unit_price) FROM product_prices x WHERE x.product_id=p.id)>0 AND ((SELECT MAX(x.unit_price) FROM product_prices x WHERE x.product_id=p.id)-(SELECT MIN(x.unit_price) FROM product_prices x WHERE x.product_id=p.id))/(SELECT AVG(x.unit_price) FROM product_prices x WHERE x.product_id=p.id)>=.20"),'in_progress'=>$q("SELECT COUNT(*) FROM price_queue WHERE status='in_progress'"),'completed'=>$q("SELECT COUNT(*) FROM price_queue WHERE status='completed'"),'workflow_active'=>$q("SELECT COUNT(*) FROM price_workflow WHERE status IN('pending','in_progress')"),'unread_notifications'=>$q("SELECT COUNT(*) FROM notifications WHERE is_read=0")];
  $trend=$pdo->query("SELECT CONVERT(date,DATEADD(month,DATEDIFF(month,0,price_received_at),0)) month_name,COUNT(*) received,AVG(unit_price) avg_price FROM product_prices WHERE price_received_at>=DATEADD(month,-5,DATEFROMPARTS(YEAR(GETDATE()),MONTH(GETDATE()),1)) GROUP BY CONVERT(date,DATEADD(month,DATEDIFF(month,0,price_received_at),0)) ORDER BY month_name")->fetchAll();
  return ['stats'=>$stats,'trend'=>$trend];
 }
 public static function prices():array{return Database::connection()->query("SELECT p.product_code,p.product_name,u.name unit_name,MAX(pp.price_received_at) latest_date,MIN(pp.unit_price) min_price,MAX(pp.unit_price) max_price,AVG(pp.unit_price) avg_price FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN product_prices pp ON pp.product_id=p.id GROUP BY p.product_code,p.product_name,u.name ORDER BY p.product_code")->fetchAll();}
 public static function filteredPrices(string $q='',int $category=0,int $importance=0):array{$pdo=Database::connection();$where=['1=1'];$p=[];if($q!==''){$where[]='(p.product_code LIKE :q OR p.product_name LIKE :q)';$p['q']='%'.$q.'%';}if($category){$where[]='p.category_id=:c';$p['c']=$category;}if($importance){$where[]='p.importance=:i';$p['i']=$importance;}$s=$pdo->prepare("SELECT p.product_code,p.product_name,u.name unit_name,c.name category_name,p.importance,MAX(pp.price_received_at) latest_date,MIN(pp.unit_price) min_price,MAX(pp.unit_price) max_price,AVG(pp.unit_price) avg_price FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN product_categories c ON c.id=p.category_id LEFT JOIN product_prices pp ON pp.product_id=p.id WHERE ".implode(' AND ',$where)." GROUP BY p.product_code,p.product_name,u.name,c.name,p.importance ORDER BY p.product_code");$s->execute($p);return $s->fetchAll();}
}